export function wrapParenthesizedExpression(
	data: T.ParenthesizedExpression & {
		readonly _parenthesized_expression_typed?:
			| T.ParenthesizedExpressionTyped
			| T.SequenceExpression
			| T.Identifier
			| T.DecoratorMemberExpression
			| T.DecoratorCallExpression;
		readonly _sequence_expression?:
			| T.ParenthesizedExpressionTyped
			| T.SequenceExpression
			| T.Identifier
			| T.DecoratorMemberExpression
			| T.DecoratorCallExpression;
		readonly _identifier?:
			| T.ParenthesizedExpressionTyped
			| T.SequenceExpression
			| T.Identifier
			| T.DecoratorMemberExpression
			| T.DecoratorCallExpression;
		readonly _member_expression?:
			| T.ParenthesizedExpressionTyped
			| T.SequenceExpression
			| T.Identifier
			| T.DecoratorMemberExpression
			| T.DecoratorCallExpression;
		readonly _call_expression?:
			| T.ParenthesizedExpressionTyped
			| T.SequenceExpression
			| T.Identifier
			| T.DecoratorMemberExpression
			| T.DecoratorCallExpression;
	},
	tree: TreeHandle
) {
	data = _keepModelledSlots(data, [
		'_content',
		'_parenthesized_expression_typed',
		'_sequence_expression',
		'_identifier',
		'_member_expression',
		'_call_expression'
	]);
	const _node = withMethods(
		{
			..._omitWrapKeys(data, [
				'_call_expression',
				'_identifier',
				'_member_expression',
				'_parenthesized_expression_typed',
				'_sequence_expression'
			]),
			$type: TSKindId.ParenthesizedExpression as const,
			_content: normalizeSingularWrapSlot(
				data._content ??
					data._parenthesized_expression_typed ??
					data._sequence_expression ??
					data._identifier ??
					data._member_expression ??
					data._call_expression,
				'content',
				true,
				data.$type,
				{ tree, nodeType: data.$type, slotName: 'content', span: (data as _NodeData).$span }
			),

			content() {
				return drillIn<
					| T.ParenthesizedExpressionTyped
					| T.SequenceExpression
					| T.Identifier
					| T.DecoratorMemberExpression
					| T.DecoratorCallExpression
				>(this._content, tree);
			},
			$with: {
				content: (v: NonNullable<T.ParenthesizedExpression['_content']>) =>
					wrapParenthesizedExpression({ ...$edited(data), _content: v }, tree)
			}
		},
		_treeEngine(tree)
	);
	return _node;
}

export function wrapExpression(
	data: T.Expression & { readonly $other?: T.Expression | readonly T.Expression[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'_as_expression',
		'_satisfies_expression',
		'_instantiation_expression',
		'_internal_module',
		'_type_assertion',
		'_primary_expression',
		'_assignment_expression',
		'_augmented_assignment_expression',
		'_await_expression',
		'_unary_expression',
		'_binary_expression',
		'_ternary_expression',
		'_update_expression',
		'_new_expression',
		'_yield_expression'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'as_expression',
		'satisfies_expression',
		'instantiation_expression',
		'internal_module',
		'type_assertion',
		'primary_expression',
		'assignment_expression',
		'augmented_assignment_expression',
		'await_expression',
		'unary_expression',
		'binary_expression',
		'ternary_expression',
		'update_expression',
		'new_expression',
		'yield_expression'
	]) as T.Expression | readonly T.Expression[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'as_expression',
			'satisfies_expression',
			'instantiation_expression',
			'internal_module',
			'type_assertion',
			'primary_expression',
			'assignment_expression',
			'augmented_assignment_expression',
			'await_expression',
			'unary_expression',
			'binary_expression',
			'ternary_expression',
			'update_expression',
			'new_expression',
			'yield_expression'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.Expression>(data as T.Expression, tree);
	}
	return drillIn<T.Expression>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

